return ['domain'=>'netdesign-session-guard','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'he_IL','project-id-version'=>'Netdesign Session Guard','pot-creation-date'=>'2026-09-28T12:14:39+00:00','po-revision-date'=>'2026-09-28T12:14:39+00:00','messages'=>['Netdesign Session Guard'=>'Netdesign Session Guard','See who is signed in right now, detect accounts shared between several people, and limit how many devices an account can use at once.'=>'ראו מי מחובר כרגע, זהו חשבונות שמשותפים בין כמה אנשים, והגבילו בכמה מכשירים ניתן להשתמש בחשבון בו-זמנית.','Netdesign'=>'Netdesign','Session Guard'=>'Session Guard','Live sessions'=>'חיבורים פעילים','Live'=>'בזמן אמת','Flagged accounts'=>'חשבונות חשודים','Settings'=>'הגדרות','User sessions'=>'חיבורי משתמש','Sign out'=>'ניתוק','Sign this device out now?'=>'לנתק את המכשיר הזה עכשיו?','Nobody is online right now.'=>'אין משתמשים מחוברים כרגע.','%ds ago'=>'לפני %d שנ׳','%dm ago'=>'לפני %d דק׳','%d devices'=>'%d מכשירים','Could not load live data.'=>'לא ניתן לטעון נתונים בזמן אמת.','Not allowed.'=>'אין הרשאה.','Email sent.'=>'האימייל נשלח.','Done.'=>'בוצע.','Sessions'=>'חיבורים','To protect accounts from unauthorized sharing, we record the devices, approximate location (IP address and country) and activity times of signed-in sessions. This data is kept for up to 90 days and is used only to detect accounts used by more than one person.'=>'כדי להגן על חשבונות משיתוף לא מורשה, אנו מתעדים את המכשירים, המיקום המשוער (כתובת IP ומדינה) וזמני הפעילות של חיבורים לחשבון. המידע נשמר עד 90 יום ומשמש רק לזיהוי חשבונות שנעשה בהם שימוש על ידי יותר מאדם אחד.','Accounts whose usage looks like more than one person. Scores add up from the rules below; review before acting.'=>'חשבונות שהשימוש בהם נראה כמו של יותר מאדם אחד. הציון מצטבר מהכללים שלהלן; מומלץ לבדוק לפני שפועלים.','Open'=>'פתוחים','Dismissed'=>'נדחו','Search users'=>'חיפוש משתמשים','User'=>'משתמש','Score'=>'ציון','Why'=>'סיבה','Updated'=>'עודכן','Actions'=>'פעולות','No flagged accounts.'=>'אין חשבונות חשודים.','Dismiss'=>'דחייה','Sign out everywhere'=>'ניתוק מכל המכשירים','Whitelist'=>'רשימה לבנה','Reopen'=>'פתיחה מחדש','Enforcing: %d device per user'=>'אכיפה: מכשיר אחד למשתמש' . "\0" . 'אכיפה: %d מכשירים למשתמש','Monitor only'=>'ניטור בלבד','Users online'=>'משתמשים מחוברים','Active sessions'=>'חיבורים פעילים','Users on 2+ devices now'=>'משתמשים על 2+ מכשירים כעת','Filter by name, email, IP or page…'=>'סינון לפי שם, אימייל, IP או עמוד…','Only users on 2+ devices'=>'רק משתמשים על 2+ מכשירים','Device'=>'מכשיר','IP / country'=>'IP / מדינה','Viewing'=>'צופה ב־','Last seen'=>'נראה לאחרונה','Device limit'=>'הגבלת מכשירים','Detection'=>'זיהוי','Advanced'=>'מתקדם','Mode'=>'מצב','Monitor only: track and flag, never sign anyone out'=>'ניטור בלבד: מעקב וסימון, ללא ניתוק משתמשים','Enforce: when a user signs in on a new device beyond the limit, the oldest device is signed out immediately'=>'אכיפה: כשמשתמש מתחבר ממכשיר חדש מעבר למגבלה, המכשיר הישן ביותר מנותק מיד','Devices allowed at once'=>'מספר מכשירים מותר בו־זמנית','Tabs in the same browser count as one device.'=>'לשוניות באותו דפדפן נחשבות כמכשיר אחד.','Roles without limits'=>'תפקידים ללא הגבלה','Not limited and never flagged.'=>'ללא הגבלה ולא מסומנים כחשודים.','Message shown to the signed-out device'=>'הודעה שתוצג במכשיר שנותק','Send signed-out device to'=>'העברת המכשיר שנותק אל','Empty = login page.'=>'ריק = עמוד ההתחברות.','Look back (days)'=>'תקופת בדיקה (ימים)','Devices online at the same time'=>'מכשירים מחוברים בו־זמנית','+40 points'=>'‎+40 נקודות','Different devices in the period'=>'מכשירים שונים בתקופה','+30 points, +5 per extra device'=>'‎+30 נקודות, ‎+5 לכל מכשיר נוסף','Different networks in the period'=>'רשתות שונות בתקופה','+20 points. A network is an IP range (/24), so a changing home IP counts once.'=>'‎+20 נקודות. רשת היא טווח כתובות (‎/24), כך ש־IP ביתי שמשתנה נספר פעם אחת.','Different countries in the period'=>'מדינות שונות בתקופה','+30 points. Needs a country header from Cloudflare or the server.'=>'‎+30 נקודות. דורש כותרת מדינה מ־Cloudflare או מהשרת.','Devices signed out by the limit'=>'מכשירים שנותקו בגלל המגבלה','+30 points. Frequent swapping between devices is a strong sign of sharing.'=>'‎+30 נקודות. החלפה תכופה בין מכשירים היא סימן חזק לשיתוף.','Flag accounts scoring at least'=>'סימון חשבונות עם ציון של לפחות','After dismissing, don\'t re-flag for (days)'=>'אחרי דחייה, לא לסמן שוב במשך (ימים)','Heartbeat every (seconds)'=>'בדיקת חיבור כל (שניות)','How fast a signed-out device notices. Only runs while the tab is visible.'=>'כמה מהר מכשיר שנותק מגלה זאת. פועל רק כשהלשונית גלויה.','Online if seen within (seconds)'=>'נחשב מחובר אם נראה בתוך (שניות)','Client IP from'=>'כתובת IP של הלקוח מתוך','Automatic (recommended): detects Cloudflare and local proxies'=>'אוטומטי (מומלץ): מזהה Cloudflare ופרוקסי מקומי','Automatic trusts a forwarding header only when the request really comes from Cloudflare or a local proxy, so visitors cannot fake their IP.'=>'במצב אוטומטי כותרת העברה נחשבת אמינה רק כשהבקשה באמת מגיעה מ־Cloudflare או מפרוקסי מקומי, כך שמבקרים לא יכולים לזייף את כתובת ה־IP שלהם.','Store anonymized IPs'=>'שמירת כתובות IP מוסתרות','Keep session history for (days)'=>'שמירת היסטוריית חיבורים למשך (ימים)','Session Guard settings'=>'הגדרות Session Guard','Session Guard Pro adds email alerts, per-user and per-LearnDash-group device limits, LearnDash course tracking and a faster heartbeat.'=>'Session Guard Pro מוסיף התראות במייל, הגבלת מכשירים לפי משתמש ולפי קבוצת LearnDash, מעקב אחר קורסי LearnDash ודופק מהיר יותר.','Learn more'=>'מידע נוסף','direct connection (REMOTE_ADDR)'=>'חיבור ישיר (REMOTE_ADDR)','Cloudflare (CF-Connecting-IP)'=>'Cloudflare (CF-Connecting-IP)','Cloudflare (real IP restored by the web server)'=>'Cloudflare (כתובת ה־IP האמיתית שוחזרה על ידי שרת האינטרנט)','local proxy (X-Forwarded-For)'=>'פרוקסי מקומי (X-Forwarded-For)','local proxy (X-Real-IP)'=>'פרוקסי מקומי (X-Real-IP)','Detected: %s'=>'זוהה: %s','Your IP as seen by Automatic:'=>'כתובת ה־IP שלך לפי המצב האוטומטי:','Enabled'=>'פעיל','User not found.'=>'המשתמש לא נמצא.','Signed out'=>'התנתק','Signed out by admin'=>'נותק על ידי מנהל','Expired'=>'פג תוקף','Password reset'=>'איפוס סיסמה','Edit user'=>'עריכת משתמש','Devices, last %d days'=>'מכשירים, %d ימים אחרונים','Networks'=>'רשתות','Countries'=>'מדינות','Logins'=>'התחברויות','Dismiss flag'=>'דחיית הסימון','Remove from whitelist'=>'הסרה מהרשימה הלבנה','Whitelisted: no limits, no flags'=>'ברשימה הלבנה: ללא הגבלות וללא סימונים','Courses'=>'קורסים','Session history'=>'היסטוריית חיבורים','Signed in'=>'התחבר','Status'=>'סטטוס','No sessions recorded yet.'=>'עדיין לא נרשמו חיבורים.','Active'=>'פעיל','Different devices'=>'מכשירים שונים','Different networks'=>'רשתות שונות','Different countries'=>'מדינות שונות','You have been signed out because your account was signed in on another device.'=>'נותקת מהאתר כי החשבון שלך התחבר ממכשיר אחר.','Session not found or already ended.'=>'החיבור לא נמצא או שכבר הסתיים.','Unknown browser'=>'דפדפן לא מזוהה','OK'=>'אישור']];